import { ALL_PLACES } from '@atlantis/shared';
import type { Place } from '@atlantis/shared';

export interface City {
  id: string;
  name: string;
  country: string;
  lat: number;
  lon: number;
  timezone: string;
}

/** IDs of places shown in CityPulse by default */
const CITYPULSE_IDS = [
  'lisbon',
  'ponta-delgada',
  'lourinha',
  'new-york',
  'san-francisco',
  'london',
  'paris',
  'berlin',
  'tokyo',
  'dubai',
  'singapore',
  'sao-paulo',
  'sydney',
];

function placeToCity(p: Place): City {
  return { id: p.id, name: p.name, country: p.country, lat: p.lat, lon: p.lng, timezone: p.timezone };
}

export const CITIES: City[] = CITYPULSE_IDS
  .map((id) => ALL_PLACES.find((p) => p.id === id))
  .filter((p): p is Place => p !== undefined)
  .map(placeToCity);

export function getCityById(id: string): City {
  return CITIES.find((c) => c.id === id) ?? CITIES[0];
}

export function aqiLabel(aqi: number): { label: string; color: string } {
  if (aqi <= 20) return { label: 'Good', color: '#3fb950' };
  if (aqi <= 40) return { label: 'Fair', color: '#d29922' };
  if (aqi <= 60) return { label: 'Moderate', color: '#f0883e' };
  if (aqi <= 80) return { label: 'Poor', color: '#f85149' };
  return { label: 'Very Poor', color: '#8957e5' };
}
